// SPDX-License-Identifier: MIT
pragma solidity ^0.8.4;

/// @title LibBitmap
/// @author Solady (https://github.com/vectorized/solady)
/// @notice A library for storage of packed booleans.
library LibBitmap {
    /*//////////////////////////////////////////////////////////////
                                STRUCTS
    //////////////////////////////////////////////////////////////*/

    /// @notice Defines a Bitmap structure that uses a mapping to store data.
    struct Bitmap {
        mapping(uint256 => uint256) map;
    }

    /*//////////////////////////////////////////////////////////////
                               CONSTANTS
    //////////////////////////////////////////////////////////////*/

    uint256 constant NOT_FOUND = type(uint256).max;

    /*//////////////////////////////////////////////////////////////
                            BITMAP OPERATIONS
    //////////////////////////////////////////////////////////////*/

    /// @notice Checks if a specific bit in a bitmap is set.
    function get(Bitmap storage bitmap, uint256 index) internal view returns (bool isSet) {
        uint256 bucket = index >> 8;
        uint256 mask = 1 << (index & 0xff);
        isSet = bitmap.map[bucket] & mask != 0;
    }

    /// @notice Sets a specific bit in the bitmap to 1.
    function set(Bitmap storage bitmap, uint256 index) internal {
        uint256 bucket = index >> 8;
        uint256 mask = 1 << (index & 0xff);
        bitmap.map[bucket] |= mask;
    }

    /// @notice Unsets a specific bit in the bitmap at the given index.
    function unset(Bitmap storage bitmap, uint256 index) internal {
        uint256 bucket = index >> 8;
        uint256 mask = ~(1 << (index & 0xff));
        bitmap.map[bucket] &= mask;
    }

    /// @notice Toggles the state of a specific bit in a bitmap storage and returns the new state.
    function toggle(Bitmap storage bitmap, uint256 index) internal returns (bool newIsSet) {
        uint256 bucket = index >> 8;
        uint256 mask = 1 << (index & 0xff);
        bitmap.map[bucket] ^= mask;
        newIsSet = bitmap.map[bucket] & mask != 0;
    }

    /// @notice Sets or unsets a bit at a specific index in a bitmap storage.
    function setTo(Bitmap storage bitmap, uint256 index, bool shouldSet) internal {
        uint256 bucket = index >> 8;
        uint256 mask = 1 << (index & 0xff);
        if (shouldSet) {
            bitmap.map[bucket] |= mask;
        } else {
            bitmap.map[bucket] &= ~mask;
        }
    }

    /// @notice Sets a batch of bits in a bitmap starting from a specific position.
    function setBatch(Bitmap storage bitmap, uint256 start, uint256 amount) internal {
        if (amount == 0) return;

        uint256 bucket = start >> 8;
        uint256 bitPos = start & 0xff;
        uint256 bitsInCurrentBucket = 256 - bitPos;

        if (amount <= bitsInCurrentBucket) {
            uint256 mask = ((1 << amount) - 1) << bitPos;
            bitmap.map[bucket] |= mask;
        } else {
            uint256 mask = type(uint256).max << bitPos;
            bitmap.map[bucket] |= mask;
            amount -= bitsInCurrentBucket;
            bucket++;

            while (amount >= 256) {
                bitmap.map[bucket] = type(uint256).max;
                amount -= 256;
                bucket++;
            }

            if (amount > 0) {
                uint256 mask = (1 << amount) - 1;
                bitmap.map[bucket] |= mask;
            }
        }
    }

    /// @notice Unsets a batch of bits in a bitmap starting from a specific position.
    function unsetBatch(Bitmap storage bitmap, uint256 start, uint256 amount) internal {
        if (amount == 0) return;

        uint256 bucket = start >> 8;
        uint256 bitPos = start & 0xff;
        uint256 bitsInCurrentBucket = 256 - bitPos;

        if (amount <= bitsInCurrentBucket) {
            uint256 mask = ((1 << amount) - 1) << bitPos;
            bitmap.map[bucket] &= ~mask;
        } else {
            uint256 mask = type(uint256).max << bitPos;
            bitmap.map[bucket] &= ~mask;
            amount -= bitsInCurrentBucket;
            bucket++;

            while (amount >= 256) {
                bitmap.map[bucket] = 0;
                amount -= 256;
                bucket++;
            }

            if (amount > 0) {
                uint256 mask = (1 << amount) - 1;
                bitmap.map[bucket] &= ~mask;
            }
        }
    }

    /// @notice Calculates the number of set bits (pop count) in a bitmap over a specified range.
    function popCount(Bitmap storage bitmap, uint256 start, uint256 amount) internal view returns (uint256 count) {
        if (amount == 0) return 0;

        uint256 bucket = start >> 8;
        uint256 bitPos = start & 0xff;
        uint256 bitsInCurrentBucket = 256 - bitPos;

        if (amount <= bitsInCurrentBucket) {
            uint256 mask = ((1 << amount) - 1) << bitPos;
            count = popcount256(bitmap.map[bucket] & mask);
        } else {
            uint256 mask = type(uint256).max << bitPos;
            count = popcount256(bitmap.map[bucket] & mask);
            amount -= bitsInCurrentBucket;
            bucket++;

            while (amount >= 256) {
                count += popcount256(bitmap.map[bucket]);
                amount -= 256;
                bucket++;
            }

            if (amount > 0) {
                uint256 mask = (1 << amount) - 1;
                count += popcount256(bitmap.map[bucket] & mask);
            }
        }
    }

    /// @notice Finds the index of the last set bit in a bitmap up to a specified index.
    function findLastSet(Bitmap storage bitmap, uint256 upTo) internal view returns (uint256 setBitIndex) {
        setBitIndex = NOT_FOUND;
        uint256 bucket = upTo >> 8;
        uint256 bitPos = upTo & 0xff;

        uint256 value = bitmap.map[bucket] & ((1 << (bitPos + 1)) - 1);
        if (value != 0) {
            setBitIndex = (bucket << 8) | (255 - clz256(value));
            return;
        }

        while (bucket > 0) {
            bucket--;
            value = bitmap.map[bucket];
            if (value != 0) {
                setBitIndex = (bucket << 8) | (255 - clz256(value));
                return;
            }
        }
    }

    /// @notice Finds the first unset bit in a bitmap within a specified range.
    function findFirstUnset(Bitmap storage bitmap, uint256 begin, uint256 upTo) internal view returns (uint256 unsetBitIndex) {
        unsetBitIndex = NOT_FOUND;
        if (begin >= upTo) return;

        uint256 bucket = begin >> 8;
        uint256 bitPos = begin & 0xff;
        uint256 lastBucket = (upTo - 1) >> 8;

        uint256 value = ~bitmap.map[bucket] & (type(uint256).max << bitPos);
        if (bucket == lastBucket) {
            value &= (1 << (upTo & 0xff)) - 1;
        }
        if (value != 0) {
            uint256 index = ctz256(value);
            unsetBitIndex = (bucket << 8) | index;
            if (unsetBitIndex < upTo) return;
        }

        bucket++;
        while (bucket <= lastBucket) {
            value = ~bitmap.map[bucket];
            if (bucket == lastBucket) {
                value &= (1 << (upTo & 0xff)) - 1;
            }
            if (value != 0) {
                uint256 index = ctz256(value);
                unsetBitIndex = (bucket << 8) | index;
                if (unsetBitIndex < upTo) return;
            }
            bucket++;
        }
    }

    /*//////////////////////////////////////////////////////////////
                           HELPER FUNCTIONS
    //////////////////////////////////////////////////////////////*/

    function popcount256(uint256 x) private pure returns (uint256 count) {
        while (x != 0) {
            x &= x - 1;
            count++;
        }
    }

    function clz256(uint256 x) private pure returns (uint256 count) {
        if (x == 0) return 256;
        count = 0;
        if (x & type(uint256).max << 128 == 0) { count += 128; x <<= 128; }
        if (x & type(uint256).max << 192 == 0) { count += 64; x <<= 64; }
        if (x & type(uint256).max << 224 == 0) { count += 32; x <<= 32; }
        if (x & type(uint256).max << 240 == 0) { count += 16; x <<= 16; }
        if (x & type(uint256).max << 248 == 0) { count += 8; x <<= 8; }
        if (x & type(uint256).max << 252 == 0) { count += 4; x <<= 4; }
        if (x & type(uint256).max << 254 == 0) { count += 2; x <<= 2; }
        if (x & type(uint256).max << 255 == 0) { count += 1; }
    }

    function ctz256(uint256 x) private pure returns (uint256 count) {
        if (x == 0) return 256;
        count = 0;
        if (x & 0xffffffffffffffffffffffffffffffff == 0) { count += 128; x >>= 128; }
        if (x & 0xffffffffffffffff == 0) { count += 64; x >>= 64; }
        if (x & 0xffffffff == 0) { count += 32; x >>= 32; }
        if (x & 0xffff == 0) { count += 16; x >>= 16; }
        if (x & 0xff == 0) { count += 8; x >>= 8; }
        if (x & 0xf == 0) { count += 4; x >>= 4; }
        if (x & 0x3 == 0) { count += 2; x >>= 2; }
        if (x & 0x1 == 0) { count += 1; }
    }
}
